using System; using System.Collections.Generic; using System.Linq; using PAP.DataAccess;
namespace PAP.Generators { public class GeneratorStatus { public string Entity {get;set;} public bool Exists {get;set;} public bool CanGenerate {get;set;} public string Reason {get;set;} } public class GeneratorCatalog { private readonly List<GeneratorBase> _items=new List<GeneratorBase>{new AddressesGenerator(), new AuthorsGenerator(), new BooksGenerator(), new CartItemsGenerator(), new CategoriesGenerator(), new CustomersGenerator(), new EmployeesGenerator(), new GenresGenerator(), new InventoryGenerator(), new OrderItemsGenerator(), new OrdersGenerator(), new PaymentsGenerator(), new PublishersGenerator(), new PurchaseOrderItemsGenerator(), new PurchaseOrdersGenerator(), new ReviewsGenerator(), new RolesGenerator(), new ShoppingCartsGenerator(), new SuppliersGenerator()}; public IEnumerable<GeneratorStatus> GetStatus(){using(var db=new BookStoreDBEntities()){return _items.Select(g=>{var count=Count(db,g.EntityName); var missing=g.Dependencies.Where(d=>Count(db,d)==0).ToList(); return new GeneratorStatus{Entity=g.EntityName,Exists=count>0,CanGenerate=count==0 && missing.Count==0 && g.EntityName!="Books",Reason=count>0?"Ya contiene datos":missing.Count>0?"Falta generar: "+String.Join(", ",missing):g.EntityName=="Books"?"Conservar el libro inicial":"Disponible"};}).ToList();}} private int Count(BookStoreDBEntities db,string name){var p=db.GetType().GetProperty(name); if(p==null)return 0; return ((System.Collections.IEnumerable)p.GetValue(db,null)).Cast<object>().Count();} public string Generate(string entity){var g=_items.FirstOrDefault(x=>x.EntityName.Equals(entity,StringComparison.OrdinalIgnoreCase)); if(g==null)throw new InvalidOperationException("Entidad no válida"); return g.Generate();} } }
